[InitializeOnLoad]public static class CityRooftopHelipads{const string D="Assets/Scenes/Oasis/YachtPortAtlas/RooftopHelipads";struct Tri{public Vector3 a,b,c;public float area;}class Site{public MeshFilter f;public Vector3 p;public float size;}static CityRooftopHelipads(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CityRooftopHelipads.request"))return;File.Delete("CityRooftopHelipads.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/CityRooftopHelipads.txt",e.ToString());Debug.LogException(e);}}static bool In(Vector3 p,Tri t){float ax=t.b.x-t.a.x,az=t.b.z-t.a.z,bx=t.c.x-t.a.x,bz=t.c.z-t.a.z,qx=p.x-t.a.x,qz=p.z-t.a.z,det=ax*bz-bx*az;if(Mathf.Abs(det)<.001f)return false;float u=(qx*bz-bx*qz)/det,v=(ax*qz-qx*az)/det;return u>=-.001f&&v>=-.001f&&u+v<=1.001f;}static void Run(){if(AssetDatabase.LoadAssetAtPath<GameObject>(D+"/City 15 Rooftop Helipads.prefab"))throw new Exception("Already built");Directory.CreateDirectory(D);var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var buildings=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>()).Where(f=>f.GetComponent<MeshRenderer>()&&f.GetComponent<MeshRenderer>().sharedMaterials.Any(m=>m&&m.name.StartsWith("Building"))&&f.GetComponent<Renderer>().bounds.size.y>18&&f.GetComponent<Renderer>().bounds.size.x>15&&f.GetComponent<Renderer>().bounds.size.z>15&&f.GetComponent<Renderer>().bounds.size.x<180&&f.GetComponent<Renderer>().bounds.size.z<180).OrderBy(f=>Mathf.Abs(f.GetComponent<Renderer>().bounds.size.y-55)).ToArray();var sites=new List<Site>();foreach(var f in buildings){if(sites.Count==15)break;var bounds=f.GetComponent<Renderer>().bounds;if(sites.Any(s=>new Vector2(s.p.x-bounds.center.x,s.p.z-bounds.center.z).sqrMagnitude<75*75))continue;var data=typeof(FinalPNGCityDetails).GetMethod("Read",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{f.sharedMesh});var type=data.GetType();var p=((Vector3[])type.GetField("p").GetValue(data)).Select(f.transform.TransformPoint).ToArray();var ids=(int[])type.GetField("ids").GetValue(data);var triangles=new List<Tri>();for(int i=0;i<ids.Length;i+=3){var a=p[ids[i]];var b=p[ids[i+1]];var c=p[ids[i+2]];var cross=Vector3.Cross(b-a,c-a);if(cross.normalized.y<.98f||Mathf.Max(a.y,Mathf.Max(b.y,c.y))-Mathf.Min(a.y,Mathf.Min(b.y,c.y))>.12f||a.y<bounds.min.y+bounds.size.y*.68f)continue;triangles.Add(new Tri{a=a,b=b,c=c,area=cross.magnitude*.5f});}Site found=null;foreach(var group in triangles.GroupBy(t=>Mathf.Round(t.a.y*10)/10).OrderByDescending(g=>g.Key)){var tris=group.ToArray();if(tris.Sum(t=>t.area)<120)continue;var min=tris.SelectMany(t=>new[]{t.a,t.b,t.c}).Aggregate(Vector3.Min);var max=tris.SelectMany(t=>new[]{t.a,t.b,t.c}).Aggregate(Vector3.Max);var center=(min+max)*.5f;var options=new[]{center}.Concat(tris.OrderByDescending(t=>t.area).Take(8).Select(t=>(t.a+t.b+t.c)/3));foreach(var candidate in options){for(float size=Mathf.Min(22,Mathf.Min(max.x-min.x,max.z-min.z)-2);size>=9;size-=2){bool fits=true;for(int x=-2;x<=2&&fits;x++)for(int z=-2;z<=2;z++){var q=candidate+new Vector3(x*size/4,0,z*size/4);if(!tris.Any(t=>In(q,t))){fits=false;break;}}if(!fits||p.Any(v=>v.y>group.Key+.25f&&Mathf.Abs(v.x-candidate.x)<size*.5f&&Mathf.Abs(v.z-candidate.z)<size*.5f))continue;found=new Site{f=f,p=new Vector3(candidate.x,group.Key+.055f,candidate.z),size=size};break;}if(found!=null)break;}if(found!=null)break;}if(found!=null)sites.Add(found);}if(sites.Count<15)throw new Exception("Only "+sites.Count+" clear fitting roofs found");var vertices=new List<Vector3>{new Vector3(-.5f,0,-.5f),new Vector3(.5f,0,-.5f),new Vector3(-.5f,0,.5f),new Vector3(.5f,0,.5f)};var uv=new List<Vector2>{new Vector2(0,0),new Vector2(1,0),new Vector2(0,1),new Vector2(1,1)};var flags=Enumerable.Repeat(new Vector4(5,0,0,1),4).ToList();var colors=Enumerable.Repeat(Color.white,4).ToList();var indices=new List<int>{0,2,1,1,2,3};for(int k=0;k<64;k++){float a=k*Mathf.PI*2/64,b=(k+1)*Mathf.PI*2/64;var p1=new Vector3(Mathf.Cos(a)*.3735f,.002f,Mathf.Sin(a)*.3735f);var p2=new Vector3(Mathf.Cos(b)*.3735f,.002f,Mathf.Sin(b)*.3735f);var p3=new Vector3(Mathf.Cos(a)*.3898f,.002f,Mathf.Sin(a)*.3898f);var p4=new Vector3(Mathf.Cos(b)*.3898f,.002f,Mathf.Sin(b)*.3898f);foreach(var triangle in new[]{new[]{p1,p2,p3},new[]{p2,p4,p3}}){if(Vector3.Cross(triangle[1]-triangle[0],triangle[2]-triangle[0]).y<0){var temp=triangle[1];triangle[1]=triangle[2];triangle[2]=temp;}foreach(var v in triangle){indices.Add(vertices.Count);vertices.Add(v);uv.Add(Vector2.zero);flags.Add(new Vector4(-1,0,0,0));colors.Add(new Color(.95f,.65f,.055f));}}}var mesh=new Mesh{name="Shared rooftop H helipad original port atlas"};mesh.SetVertices(vertices);mesh.SetUVs(0,uv);mesh.SetUVs(1,flags);mesh.SetColors(colors);mesh.SetTriangles(indices,0);mesh.RecalculateNormals();mesh.RecalculateBounds();mesh.Optimize();AssetDatabase.CreateAsset(mesh,D+"/Shared Rooftop Helipad.asset");var template=new GameObject("Shared atlas rooftop helipad marking");template.AddComponent<MeshFilter>().sharedMesh=mesh;var renderer=template.AddComponent<MeshRenderer>();renderer.sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/YachtPortAtlas/Shared Yacht Yard Atlas.mat");renderer.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;var lod=template.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.002f,new[]{renderer})});lod.RecalculateBounds();PrefabUtility.SaveAsPrefabAsset(template,D+"/Shared Atlas Rooftop Helipad.prefab");UnityEngine.Object.DestroyImmediate(template);var root=new GameObject("City 15 Rooftop Helipads");var report="";for(int i=0;i<sites.Count;i++){var site=sites[i];var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(D+"/Shared Atlas Rooftop Helipad.prefab"),root.transform);g.name="Roof helipad "+(i+1)+" - "+site.f.name;g.transform.position=site.p;g.transf